#pragma once
// NRH2 is deliberately independent of the CPU v1 and donor v11 protocols.
#include <inputs/universal_feeder/GpuFrameTicket.h>
#include <dlssnr/PreparedTransportProtocol.h>
#include <nr/context/PreparedGuideNormalization.h>
#include <bit>
#include <algorithm>
#include <vector>
namespace nrpg::gpu {
namespace P=Neurotic::Feed::Prepared;
namespace T=Neurotic::Connections;
using Nonce=std::array<std::uint64_t,2>;
inline constexpr Nonce BuildIdentity{0x4e52483200020001ULL,0x0000202610050001ULL};
constexpr std::uint32_t Magic=0x3248524e,MaxBytes=4096;
enum class Kind:std::uint16_t { Hello=1,HelloAck,Register,Frame,Result,Release,Drain,Cancel,Close };
enum class Role:std::uint32_t { Color=1,Depth,Motion,Distrust,Output,ProducerFence,OutputFence };
enum class ObjectKind:std::uint32_t { Texture=1,Fence=2 };
enum class Direction:std::uint32_t { ProducerToHost=1,HostToProducer=2 };
enum Capabilities:std::uint32_t { PreparedExports=1,SharedTextures=2,SharedFences=4,PixelRoundtrip=8,DirectNRReady=16 };
struct Hello { Nonce nonce{};std::uint64_t adapterLuid=0;std::uint32_t processId=0,processBits=0,consumerMode=1,descriptorVersion=1,capabilities=0;Nonce buildIdentity{}; };
struct GpuRegistration { Nonce nonce{};T::Identity identity{};std::uint32_t id=0,slot=0;Role role=Role::Color;ObjectKind kind=ObjectKind::Texture;std::uint64_t handle=0;std::uint32_t width=0,height=0,format=0,mips=0,arraySize=0,samples=0,access=0;Direction direction=Direction::ProducerToHost; };
struct GpuFrameRequest { T::FrameTicket ticket{};P::Descriptor description{};std::array<std::uint32_t,5> registrations{}; };
struct GpuFrameResult { T::FrameTicket ticket{};P::Ipc::Outcome outcome=P::Ipc::Outcome::Failed;std::uint32_t facts=0;std::uint64_t outputCapture=0,completedValue=0;std::uint32_t reason=0;std::uint64_t durationUs=0; };
struct Command { T::FrameTicket ticket{};std::uint32_t facts=0; };
using Bytes=std::vector<std::uint8_t>;
inline std::size_t PayloadSize(Kind k){switch(k){case Kind::Hello:case Kind::HelloAck:return 64;case Kind::Register:return 128;case Kind::Frame:return 400;case Kind::Result:return 160;case Kind::Release:case Kind::Drain:case Kind::Cancel:case Kind::Close:return 128;default:return 0;}}
inline void Put(std::span<std::uint8_t>b,std::size_t o,std::uint64_t v,unsigned n=8){T::detail::Put(b,o,v,n);}
inline std::uint64_t Get(std::span<const std::uint8_t>b,std::size_t o,unsigned n=8){return T::detail::Get(b,o,n);}
inline Bytes Envelope(Kind k){Bytes b(16+PayloadSize(k));Put(b,0,Magic,4);Put(b,4,2,2);Put(b,6,static_cast<unsigned>(k),2);Put(b,8,b.size(),4);return b;}
inline bool Header(std::span<const std::uint8_t>b,Kind& k){if(b.size()<16||Get(b,0,4)!=Magic||Get(b,4,2)!=2||Get(b,12,4))return false;k=static_cast<Kind>(Get(b,6,2));auto n=PayloadSize(k);return n&&Get(b,8,4)==n+16&&n+16<=MaxBytes;}
inline bool Payload(std::span<const std::uint8_t>b,Kind k,std::span<const std::uint8_t>&p){Kind actual{};if(!Header(b,actual)||actual!=k||b.size()!=16+PayloadSize(k))return false;p=b.subspan(16);return true;}
inline void Prefix(std::span<std::uint8_t>b,std::size_t o,const T::Identity&i){for(auto v:{i.producer,i.session,i.stream,i.device,i.generation}){Put(b,o,v);o+=8;}}
inline T::Identity Prefix(std::span<const std::uint8_t>b,std::size_t o){return {Get(b,o),Get(b,o+8),Get(b,o+16),Get(b,o+24),Get(b,o+32),0};}
inline bool Zero(std::span<const std::uint8_t>b){return std::all_of(b.begin(),b.end(),[](auto v){return !v;});}
inline Bytes Encode(const Hello& h,Kind k=Kind::Hello){auto b=Envelope(k);auto p=std::span(b).subspan(16);Put(p,0,h.nonce[0]);Put(p,8,h.nonce[1]);Put(p,16,h.adapterLuid);Put(p,24,h.processId,4);Put(p,28,h.processBits,4);Put(p,32,h.consumerMode,4);Put(p,36,h.descriptorVersion,4);Put(p,40,h.capabilities,4);Put(p,48,h.buildIdentity[0]);Put(p,56,h.buildIdentity[1]);return b;}
inline bool Decode(std::span<const std::uint8_t>b,Hello& h,Kind k=Kind::Hello){std::span<const std::uint8_t>p;if(!Payload(b,k,p)||Get(p,44,4))return false;h={{Get(p,0),Get(p,8)},Get(p,16),static_cast<std::uint32_t>(Get(p,24,4)),static_cast<std::uint32_t>(Get(p,28,4)),static_cast<std::uint32_t>(Get(p,32,4)),static_cast<std::uint32_t>(Get(p,36,4)),static_cast<std::uint32_t>(Get(p,40,4)),{Get(p,48),Get(p,56)}};return (h.nonce[0]||h.nonce[1])&&h.adapterLuid&&h.processId&&(h.processBits==32||h.processBits==64)&&h.consumerMode>=1&&h.consumerMode<=2&&h.descriptorVersion==1&&!(h.capabilities&~31U)&&(!(h.capabilities&DirectNRReady)||h.consumerMode==1);}
inline Bytes Encode(const GpuRegistration&r){auto b=Envelope(Kind::Register);auto p=std::span(b).subspan(16);Put(p,0,r.nonce[0]);Put(p,8,r.nonce[1]);Prefix(p,16,r.identity);Put(p,56,r.id,4);Put(p,60,r.slot,4);Put(p,64,static_cast<unsigned>(r.role),4);Put(p,68,static_cast<unsigned>(r.kind),4);Put(p,72,r.handle);unsigned o=80;for(auto v:{r.width,r.height,r.format,r.mips,r.arraySize,r.samples,r.access,static_cast<unsigned>(r.direction)}){Put(p,o,v,4);o+=4;}return b;}
inline bool Decode(std::span<const std::uint8_t>b,GpuRegistration&r){std::span<const std::uint8_t>p;if(!Payload(b,Kind::Register,p)||!Zero(p.subspan(112)))return false;r.nonce={Get(p,0),Get(p,8)};r.identity=Prefix(p,16);r.id=static_cast<std::uint32_t>(Get(p,56,4));r.slot=static_cast<std::uint32_t>(Get(p,60,4));r.role=static_cast<Role>(Get(p,64,4));r.kind=static_cast<ObjectKind>(Get(p,68,4));r.handle=Get(p,72);std::uint32_t*fields[]={&r.width,&r.height,&r.format,&r.mips,&r.arraySize,&r.samples,&r.access};unsigned o=80;for(auto*f:fields){*f=static_cast<std::uint32_t>(Get(p,o,4));o+=4;}r.direction=static_cast<Direction>(Get(p,108,4));const auto role=static_cast<unsigned>(r.role);return (r.nonce[0]||r.nonce[1])&&r.id&&r.slot<2&&(r.handle||(r.kind==ObjectKind::Texture&&r.direction==Direction::HostToProducer))&&role>=1&&role<=7&&(r.direction==Direction::ProducerToHost||r.direction==Direction::HostToProducer)&&((role>=6&&r.kind==ObjectKind::Fence&&!r.width&&!r.height&&!r.format&&!r.mips&&!r.arraySize&&!r.samples)||(role<=5&&r.kind==ObjectKind::Texture&&T::AdmitRaster(r.width,r.height)&&r.mips==1&&r.arraySize==1&&r.samples==1));}
// Each field is written independently; native Descriptor packing is never wire authority.
inline void DescriptorBytes(std::span<std::uint8_t>b,const P::Descriptor&d){unsigned o=0;auto u32=[&](std::uint32_t v){Put(b,o,v,4);o+=4;};auto u64=[&](std::uint64_t v){Put(b,o,v);o+=8;};u32(d.size);u32(d.version);for(auto v:{d.producer,d.session,d.stream,d.device,d.generation,d.capture,d.previousCapture,d.maskCapture})u64(v);for(auto r:{d.color,d.depth,d.motion,d.distrust})for(auto v:{r.allocationWidth,r.allocationHeight,r.x,r.y,r.width,r.height})u32(v);for(auto v:{static_cast<unsigned>(d.colorOrigin),static_cast<unsigned>(d.depthOrigin),static_cast<unsigned>(d.motionOrigin),static_cast<unsigned>(d.maskOrigin),static_cast<unsigned>(d.sourceApi),static_cast<unsigned>(d.colorDomain),static_cast<unsigned>(d.depthKind),static_cast<unsigned>(d.motionUnits),static_cast<unsigned>(d.motionDirection),static_cast<unsigned>(d.rasterOrigin),d.motionGridWidth,d.motionGridHeight,std::bit_cast<std::uint32_t>(d.scaleX),std::bit_cast<std::uint32_t>(d.scaleY),d.depthReversed,d.flags})u32(v);for(auto v:d.reserved)u32(v);}
inline bool DescriptorBytes(std::span<const std::uint8_t>b,P::Descriptor&d){if(b.size()!=248)return false;unsigned o=0;auto u32=[&](){auto v=static_cast<std::uint32_t>(Get(b,o,4));o+=4;return v;};auto u64=[&](){auto v=Get(b,o);o+=8;return v;};d.size=u32();d.version=u32();for(auto*p:{&d.producer,&d.session,&d.stream,&d.device,&d.generation,&d.capture,&d.previousCapture,&d.maskCapture})*p=u64();for(auto*r:{&d.color,&d.depth,&d.motion,&d.distrust}){r->allocationWidth=u32();r->allocationHeight=u32();r->x=u32();r->y=u32();r->width=u32();r->height=u32();}d.colorOrigin=static_cast<P::C::SourceClass>(u32());d.depthOrigin=static_cast<P::C::SourceClass>(u32());d.motionOrigin=static_cast<P::C::SourceClass>(u32());d.maskOrigin=static_cast<P::C::SourceClass>(u32());d.sourceApi=static_cast<P::C::GraphicsApi>(u32());d.colorDomain=static_cast<P::C::ColorDomain>(u32());d.depthKind=static_cast<P::C::DepthKind>(u32());d.motionUnits=static_cast<P::C::MotionUnits>(u32());d.motionDirection=static_cast<P::C::MotionDirection>(u32());d.rasterOrigin=static_cast<P::C::RasterOrigin>(u32());d.motionGridWidth=u32();d.motionGridHeight=u32();d.scaleX=std::bit_cast<float>(u32());d.scaleY=std::bit_cast<float>(u32());d.depthReversed=u32();d.flags=u32();for(auto&v:d.reserved)v=u32();return bool(Neurotic::Context::NormalizePreparedGuides(d));}
inline bool Matches(const GpuFrameRequest&r){const auto&d=r.description;return r.ticket.identity==T::Identity{d.producer,d.session,d.stream,d.device,d.generation,d.capture}&&bool(r.ticket.flags&1)==bool(d.flags&P::Reset)&&T::AdmitRaster(d.color.width,d.color.height)&&r.registrations[0]&&r.registrations[1]&&r.registrations[4]&&((r.ticket.flags&2)?(r.registrations[2]&&r.registrations[3]&&(d.flags&P::HasDistrust)):(!r.registrations[2]&&!r.registrations[3]));}
inline Bytes Encode(const GpuFrameRequest&r){auto b=Envelope(Kind::Frame);auto p=std::span(b).subspan(16);auto t=T::Encode(r.ticket);std::copy(t.begin(),t.end(),p.begin());DescriptorBytes(p.subspan(120,248),r.description);for(unsigned i=0;i<5;++i)Put(p,368+i*4,r.registrations[i],4);return b;}
inline bool Decode(std::span<const std::uint8_t>b,GpuFrameRequest&r){std::span<const std::uint8_t>p;if(!Payload(b,Kind::Frame,p)||!Zero(p.subspan(388))||!T::Decode(p.first(120),r.ticket)||!DescriptorBytes(p.subspan(120,248),r.description))return false;for(unsigned i=0;i<5;++i)r.registrations[i]=static_cast<std::uint32_t>(Get(p,368+i*4,4));return Matches(r);}
inline Bytes Encode(const GpuFrameResult&r){auto b=Envelope(Kind::Result);auto p=std::span(b).subspan(16);auto t=T::Encode(r.ticket);std::copy(t.begin(),t.end(),p.begin());Put(p,120,static_cast<unsigned>(r.outcome),4);Put(p,124,r.facts,4);Put(p,128,r.outputCapture);Put(p,136,r.completedValue);Put(p,144,r.reason,4);Put(p,152,r.durationUs);return b;}
inline bool Decode(std::span<const std::uint8_t>b,GpuFrameResult&r){std::span<const std::uint8_t>p;if(!Payload(b,Kind::Result,p)||Get(p,148,4)||!T::Decode(p.first(120),r.ticket))return false;r.outcome=static_cast<P::Ipc::Outcome>(Get(p,120,4));r.facts=static_cast<std::uint32_t>(Get(p,124,4));r.outputCapture=Get(p,128);r.completedValue=Get(p,136);r.reason=static_cast<std::uint32_t>(Get(p,144,4));r.durationUs=Get(p,152);P::Ipc::Result check;auto&i=r.ticket.identity;check.identity={i.producer,i.session,i.stream,i.device,i.generation,i.capture};check.state=r.outcome;check.facts=r.facts;check.outputCapture=r.outputCapture;check.completionValue=r.completedValue;return P::Ipc::Valid(check)&&(!(r.facts&P::Ipc::OutputValid)||r.completedValue==r.ticket.outputValue);}
inline Bytes Encode(const Command&c,Kind k){auto b=Envelope(k);auto p=std::span(b).subspan(16);auto t=T::Encode(c.ticket);std::copy(t.begin(),t.end(),p.begin());Put(p,120,c.facts,4);return b;}
inline bool Decode(std::span<const std::uint8_t>b,Command&c,Kind k){std::span<const std::uint8_t>p;if(!Payload(b,k,p)||p.size()!=128||Get(p,124,4)||!T::Decode(p.first(120),c.ticket))return false;c.facts=static_cast<std::uint32_t>(Get(p,120,4));return k==Kind::Release?c.facts==3:c.facts==0;}
static_assert(sizeof(T::TicketBytes)==120&&sizeof(P::Descriptor)==248);
}
